 public float Radius=3.5f;IslandNavigation nav;CreatureHybrid creature;CarryItem item;PhysicsScene physics;Scene scene;Mesh ground;Material material;Texture2D stripes;PhysicsMaterial rubber;bool heldBefore,credited,creatureThrow,thrown;float elapsed,refresh;int witnesses;readonly HashSet<string> struck=new HashSet<string>();readonly List<PlayImpactTarget> targets=new List<PlayImpactTarget>();readonly List<BallCollisionProxy> pool=new List<BallCollisionProxy>();VillagerSocial[] villagers;
 Rigidbody creatureContact; Vector3 previousCreature, contactVelocity; bool contactReady, kicking; float kickReward;
 public string StableId=>GetComponent<HybridTarget>()?.id??"beachball";
 public void Initialize(IslandNavigation navigation){nav=navigation;item=GetComponent<CarryItem>();transform.localScale=Vector3.one*nav.Scale*Radius*2;var origin=transform.position;var obstacles=nav.GetComponentsInChildren<IslandPlacementView>().Where(v=>v.kind=="building"||v.kind=="tree").ToArray();var trays=nav.GetComponentsInChildren<ConstructionSite>();var vessels=nav.GetComponentsInChildren<WaterVessel>();float bestSlope=float.MaxValue;var searchOrigin=origin;for(int i=0;i<600;i++){float angle=i*137.5f*Mathf.Deg2Rad;var wanted=searchOrigin+new Vector3(Mathf.Cos(angle),0,Mathf.Sin(angle))*(10+i*.3f)*nav.Scale;if(!nav.Sample(wanted,nav.creature,1,out var clear)||!nav.Sample(clear,nav.villager,1,out _))continue;clear=nav.ProjectFoot(clear,nav.creature);if(obstacles.Any(v=>new Vector2(v.transform.position.x-clear.x,v.transform.position.z-clear.z).magnitude<nav.Scale*20)||trays.Any(t=>Vector3.Distance(t.transform.position,clear)<nav.Scale*22)||vessels.Any(v=>Vector3.Distance(v.transform.position,clear)<nav.Scale*15))continue;float slope=0;foreach(var direction in new[]{Vector3.forward,Vector3.back,Vector3.left,Vector3.right})slope=Mathf.Max(slope,Mathf.Abs(nav.ProjectFoot(clear+direction*nav.Scale*12,nav.creature).y-clear.y)/nav.Scale);if(slope>=bestSlope)continue;bestSlope=slope;origin=clear;if(slope<.25f)break;}transform.position=nav.ProjectFoot(origin,nav.creature)+Vector3.up*nav.Scale*Radius;item.home=transform.position;
  stripes=new Texture2D(96,48,TextureFormat.RGBA32,false){wrapMode=TextureWrapMode.Repeat};var colors=new[]{new Color(.95f,.2f,.12f),Color.white,new Color(.12f,.55f,.9f),Color.white,new Color(.98f,.8f,.12f),Color.white};var pixels=new Color[96*48];for(int y=0;y<48;y++)for(int x=0;x<96;x++)pixels[y*96+x]=y<3||y>44?Color.white:colors[x/16];stripes.SetPixels(pixels);stripes.Apply();material=new Material(Shader.Find("BWVR/GameSurface")){mainTexture=stripes,color=Color.white};GetComponent<Renderer>().sharedMaterial=material;
