  Bounds BoxBounds(BoxCollider box){var matrix=box.transform.localToWorldMatrix;var x=matrix.MultiplyVector(Vector3.right*box.size.x*.5f);var y=matrix.MultiplyVector(Vector3.up*box.size.y*.5f);var z=matrix.MultiplyVector(Vector3.forward*box.size.z*.5f);var extents=new Vector3(Mathf.Abs(x.x)+Mathf.Abs(y.x)+Mathf.Abs(z.x),Mathf.Abs(x.y)+Mathf.Abs(y.y)+Mathf.Abs(z.y),Mathf.Abs(x.z)+Mathf.Abs(y.z)+Mathf.Abs(z.z));return new Bounds(box.transform.TransformPoint(box.center),extents*2);}
  foreach(var view in nav.GetComponentsInChildren<IslandPlacementView>()){if(view.kind!="tree"&&view.kind!="building")continue;if(view.kind=="tree"&&nav.Terrain!=null&&Array.Exists(nav.Terrain.placements,p=>p.line==view.sourceLine&&p.variant>=13&&p.variant<=15))continue;Bounds bounds;if(view.kind=="tree")bounds=new Bounds(view.transform.position+Vector3.up*nav.Scale*4,new Vector3(2,8,2)*nav.Scale);else{var colliders=view.GetComponentsInChildren<BoxCollider>();if(colliders.Length==0)continue;bounds=BoxBounds(colliders[0]);foreach(var c in colliders)bounds.Encapsulate(BoxBounds(c));}var target=view.gameObject.AddComponent<PlayImpactTarget>();target.Initialize("placement-"+view.sourceLine,view.kind,bounds);targets.Add(target);}
