 public Vector3 Direction(Transform actor){Vector3 best=actor.forward;float risk=float.MaxValue;for(int i=0;i<8;i++){var direction=Quaternion.Euler(0,(creature.State.decisions*47+i*45)%360,0)*Vector3.forward;float score=0;foreach(var target in targets){var delta=target.Bounds(nav.Scale).center-actor.position;delta.y=0;float forward=Vector3.Dot(delta,direction)/nav.Scale;if(forward>0&&forward<65){float side=(delta-direction*Vector3.Dot(delta,direction)).magnitude/nav.Scale;if(side<Radius+3)score+=target.kind=="villager"?3:1;}}if(i==0&&creature.Season.WorldPlay.caution<.45f)return direction;if(score<risk){risk=score;best=direction;}}return best;}
 public void Throw(Vector3 direction,bool byCreature=true,float speed=18){creature.ClearBowlRebuild();CancelCourseShot();ResetInventionThrow();Bowling?.CancelAttempt();JustFetched=false;CancelFetch();lastPeerKicker=null;kicking=false;direction.y=0;if(direction.sqrMagnitude<.01f)direction=Vector3.forward;item.held=false;heldBefore=false;GetComponent<Collider>().enabled=true;Body.isKinematic=false;Body.position=nav.ToNav(transform.position);Body.rotation=transform.rotation;Body.linearVelocity=direction.normalized*Mathf.Clamp(speed,1,24)+Vector3.up*7;Body.angularVelocity=Vector3.Cross(Vector3.up,direction.normalized)*3;Body.WakeUp();InFlight=true;thrown=true;Harmful=false;credited=false;creatureThrow=byCreature;elapsed=0;witnesses=0;struck.Clear();refresh=0;blockRefresh=0;Goals?.Begin(byCreature);if(byCreature)creature.Season.WorldPlay.throws=Math.Min(1000000,creature.Season.WorldPlay.throws+1);}
 void RefreshContacts(){var near=targets.Where(t=>t!=null&&t.GetComponent<CarryItem>()?.held!=true&&(t.Bounds(nav.Scale).center-transform.position).sqrMagnitude<nav.Scale*nav.Scale*10000).OrderBy(t=>(t.Bounds(nav.Scale).center-transform.position).sqrMagnitude).Take(pool.Count).ToArray();for(int i=0;i<pool.Count;i++){var proxy=pool[i];proxy.target=i<near.Length?near[i]:null;proxy.gameObject.SetActive(proxy.target!=null);if(proxy.target==null)continue;var bounds=proxy.target.Bounds(nav.Scale);proxy.GetComponent<BoxCollider>().size=bounds.size/nav.Scale;proxy.GetComponent<Rigidbody>().position=nav.ToNav(bounds.center);}}
 public void Advance(float dt,bool paused){if(creature==null)return;if(paused||dt<=0){contactReady=false;return;}Puzzle?.Advance(Mathf.Min(dt,.1f));Goals?.Advance(Mathf.Min(dt,.1f));Spin?.Advance(Mathf.Min(dt,.1f));Chase?.Advance(Mathf.Min(dt,.1f));AdvanceFetch();dt=Mathf.Min(dt,.1f);var next=nav.ToNav(creature.transform.position)+Vector3.up*2;contactVelocity=contactReady?(next-previousCreature)/dt:Vector3.zero;contactVelocity.y=0;contactReady=true;previousCreature=next;if(contactVelocity.magnitude>30)contactVelocity=Vector3.zero;creatureContact.position=next;creatureContact.GetComponent<Collider>().enabled=creature.GetComponent<CarryItem>()?.held!=true&&!creature.GetComponent<CreatureCuriosity>().HandlingBeachBall;
SyncBlockContacts(dt);
if(item.held){CancelBuildBowlShot();if(BowlCreaturePending||creature.GetComponent<CreatureCuriosity>().Holding!=item)ClearBowlCreatureTurn();if(!fetchClaimed&&creature.GetComponent<CreatureCuriosity>().Holding!=item)Goals?.Turns.PlayerGrab();Goals?.Cancel();if(!fetchClaimed)CancelFetch();CancelRally();thrown=false;Body.isKinematic=true;Body.position=nav.ToNav(transform.position);Body.rotation=transform.rotation;heldBefore=true;if(Bowling?.Available==true||Goals!=null){for(float remaining=dt;remaining>0;remaining-=.02f){float step=Mathf.Min(.02f,remaining);Goals?.BeforeStep(step);SyncBlockContacts(0);physics.Simulate(step);if(!item.held){Goals?.AfterStep(step);Puzzle?.AfterPhysics(step);}}Bowling?.Tick(dt);}return;}if(heldBefore){heldBefore=false;Body.isKinematic=false;Body.position=nav.ToNav(transform.position);Body.linearVelocity=Vector3.zero;Body.angularVelocity=Vector3.zero;}refresh-=dt;if(refresh<=0){refresh=.25f;RefreshContacts();}foreach(var proxy in pool)if(proxy.target?.villager!=null)proxy.GetComponent<Rigidbody>().position=nav.ToNav(proxy.target.Bounds(nav.Scale).center);
  for(float remaining=dt;remaining>0;remaining-=.02f){float step=Mathf.Min(.02f,remaining);Goals?.BeforeStep(step);SyncBlockContacts(0);physics.Simulate(step);if(!item.held){Goals?.AfterStep(step);Puzzle?.AfterPhysics(step);}}transform.SetPositionAndRotation(nav.ToWorld(Body.position),Body.rotation);Bowling?.Tick(dt);if(thrown){elapsed+=dt;if(elapsed>12)thrown=false;}if(InFlight&&elapsed>(kicking&&kickReward<.02f?.6f:4))FinishExperience();AdvanceRally(dt);if(transform.position.y<(nav.Terrain?.SeaLevel??.7f)-nav.Scale*15||(transform.position-item.home).sqrMagnitude>nav.Scale*nav.Scale*90000){FinishExperience();ReturnHome();}AdvanceBuildBowlShot(dt);AdvanceBowlCreatureShot(dt);
 }
 public void CreatureContact(Collider collider){if(BuildBowlPending||BowlCreaturePending||FetchReserved||creatureContact==null||collider.attachedRigidbody!=creatureContact||item.held||creature.GetComponent<CreatureCuriosity>().HandlingBeachBall||InFlight||contactVelocity.magnitude<.6f||creature.State.time<creature.Season.WorldPlay.nextKick)return;var direction=Body.position-creatureContact.position;direction.y=0;if(direction.sqrMagnitude<.01f||Vector3.Dot(contactVelocity,direction.normalized)<.5f)return;float speed=Mathf.Clamp(Vector3.Dot(contactVelocity,direction.normalized)*1.25f,1,20);if(PeerGame)CancelRally();Throw(direction,true,speed);kicking=true;kickReward=speed<8?.012f:.045f;Body.linearVelocity=direction.normalized*speed+Vector3.up*Mathf.Min(2,speed*.1f);creature.Season.WorldPlay.nextKick=creature.State.time+(speed<8?1.2f:7);creature.Season.WorldPlay.kicks=Math.Min(1000000,creature.Season.WorldPlay.kicks+1);}
 public void SoundContact(float speed){if(creature==null||creature.Season.paused||item.held||speed<1.4f)return;IslandAudio.Cue(IslandSound.Ball,nav.ToWorld(Body.position),GetEntityId().GetHashCode(),Mathf.Clamp01(speed/14),1);}
 public void Impact(PlayImpactTarget target,float speed){if(target==null||!thrown||speed<9||!struck.Add(target.id))return;collisions++;if(!Harmful&&credited&&creatureThrow){var late=creature.Season.WorldPlay;late.safeThrows=Math.Max(0,late.safeThrows-1);late.harmfulThrows=Math.Min(late.throws,late.harmfulThrows+1);late.throwingFun=Mathf.Clamp01(late.throwingFun-.1f);late.caution=Mathf.Clamp01(late.caution+.18f);creature.State.Experience(StableId,-.15f);}RetractInvention();Harmful=true;NotifyObservers(false);CancelRally();float damage=creature.Season.WorldPlay.Hurt(target.id,Mathf.Clamp((speed-7)*.07f,.1f,.65f));target.Apply(damage);if(target.villager!=null)target.villager.Memory.injury=Mathf.Clamp01(target.villager.Memory.injury+.35f);foreach(var villager in villagers){int identity=Array.IndexOf(villagers,villager);if((witnesses&(1<<identity))!=0||Vector3.Distance(villager.transform.position,target.transform.position)>nav.Scale*55)continue;witnesses|=1<<identity;villager.ReactToBall(transform,creatureThrow);WitnessPeerHarm(villager);}
  if(creatureThrow){creature.GetComponent<CreatureCuriosity>().NoticeBadPlay(target.transform);creature.Journal.Add(creature.State.time,"harmful throw",CreatureAction.PlayWithToy,StableId,target.id+" damage "+damage.ToString("F2"));}else creature.Journal.Add(creature.State.time,lastPeerKicker!=null?"villager ball impact":"player ball impact",CreatureAction.IdleOrObserve,target.id,"No creature blame");
 }
 public void FinishExperience(){if(!InFlight)return;InFlight=false;if(credited||!creatureThrow)return;credited=true;ConfirmInvention();var memory=creature.Season.WorldPlay;if(Harmful){memory.harmfulThrows=Math.Min(memory.throws,memory.harmfulThrows+1);memory.caution=Mathf.Clamp01(memory.caution+.18f);creature.State.Experience(StableId,-.1f);}else{memory.safeThrows=Math.Min(memory.throws,memory.safeThrows+1);memory.throwingFun=Mathf.Clamp01(memory.throwingFun+.1f);creature.State.Experience(StableId,kicking?kickReward:.06f);creature.GetComponent<CreatureCuriosity>().NoticeGreeting(transform);}creature.Journal.Add(creature.State.time,Harmful?"throw caution learned":"throwing discovered as fun",CreatureAction.PlayWithToy,StableId,"Confirmed physical outcome");}
 public void EnvironmentalImpulse(Vector3 velocity){if(item.held)return;CancelCourseShot();Goals?.Turns.Cancel("Wind moved the ball");Goals?.Cancel();CancelFetch();CancelRally();creatureThrow=false;thrown=InFlight=false;Body.isKinematic=false;Body.linearVelocity+=velocity;Body.WakeUp();}
 public void ReturnHome(bool keepGoalGame=false){CancelCourseShot();ResetInventionThrow();Puzzle?.BallMoved();Spin?.Cancel();if(!keepGoalGame)Goals?.Turns.Cancel("Ball returned home");Goals?.Cancel();Bowling?.CancelAttempt();JustFetched=false;CancelFetch();CancelRally();Harmful=false;thrown=InFlight=false;Body.isKinematic=false;Body.position=nav.ToNav(item.home);Body.rotation=Quaternion.identity;Body.linearVelocity=Body.angularVelocity=Vector3.zero;transform.SetPositionAndRotation(item.home,Quaternion.identity);item.held=false;heldBefore=false;blockRefresh=0;GetComponent<Collider>().enabled=true;}
 // Explicit handoff also covers a grab/release occurring between simulation ticks.
 public void PlaceOnGround(Vector3 groundPoint,bool keepGoalGame=false){var rotation=transform.rotation;ReturnHome(keepGoalGame);Body.position=nav.ToNav(groundPoint)+Vector3.up*Radius;Body.rotation=rotation;transform.SetPositionAndRotation(nav.ToWorld(Body.position),rotation);Body.WakeUp();contactReady=false;refresh=0;blockRefresh=0;}
 public void ResetWorld(){Puzzle?.Reset();Spin?.Reset();Goals?.ResetWorld();Chase?.Reset();InFlight=false;ReturnHome();Bowling?.ResetRack(false);Bowling?.ClearDemonstration();foreach(var target in targets)if(target!=null)target.Apply(creature.Season.WorldPlay.Damage(target.id));}
 void OnDestroy(){handoffCues?.Dispose();Puzzle?.Dispose();Goals?.Dispose();Bowling?.Dispose();if(fetchRing!=null)Destroy(fetchRing.gameObject);if(material!=null)Destroy(material);if(stripes!=null)Destroy(stripes);if(rubber!=null)Destroy(rubber);if(ground!=null)Destroy(ground);if(scene.IsValid()&&scene.isLoaded)SceneManager.UnloadSceneAsync(scene);}
